import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"安全","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/usage/security.md","filePath":"zh-Hans/usage/security.md","lastUpdated":1795853957000}`),a={name:`zh-Hans/usage/security.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h1><p>Sync Engine 处理你的仓库文件、远端存储凭据和可执行模块。本页说明它信任什么、不能保护什么，以及你能做什么来降低风险。</p><h2 id="信任边界" tabindex="-1">信任边界 <a class="header-anchor" href="#信任边界" aria-label="Permalink to “信任边界”">​</a></h2><p>Sync Engine 信任本地操作系统、Obsidian 和运行它的设备。任何能控制你的设备或 Obsidian 会话的人或软件，也可能访问你的仓库和配置的凭据。Sync Engine 无法防护已被攻破的设备。</p><p>Sync Engine 也假定用户对自己的安全是理性的：只要用户明确批准，它允许一切。</p><p>模块是可执行代码。启用的模块可以获得广泛的 Obsidian 和 Sync Engine 权限，包括仓库文件和网络请求。这是可扩展设计的必然结果，但这也意味着你应该像对待插件一样对待模块，只启用你信任的模块。</p><p>没有客户端加密时，你同步的文件会到达配置的后端。因此，后端和网络都应被视为你的数据可能被读取或修改的地方。<a href="./../deep-dive/modules/encryption">加密模块</a>让客户端在上传前加密文件内容和文件名。它不能隐藏所有细节：后端仍然可以得知文件大小、修改时间、文件数量等信息，也仍然可以删除或回滚远端数据。</p><h2 id="sync-engine-做了什么" tabindex="-1">Sync Engine 做了什么 <a class="header-anchor" href="#sync-engine-做了什么" aria-label="Permalink to “Sync Engine 做了什么”">​</a></h2><ul><li>只有配置的后端和模块源会收到请求。Sync Engine 没有遥测。请求的时机和范围见<a href="./permissions">权限</a>。</li><li>新模块默认禁用。Sync Engine 把你的批准记录与模块文件分开保存，并在加载前检查模块完整性，除非你显式关闭该检查。确切的边界见<a href="./../deep-dive/extensibility">扩展性契约</a>。</li><li>自动更新只作用于来自同一来源的已安装模块。没有下载记录的新模块会以禁用状态安装，在你启用之前不会被加载。</li><li>官方模块只读取其文档所述功能需要的密钥。密钥通过 Obsidian 的密钥存储保存，而不是普通设置。</li><li>每个官方模块在获得&quot;官方&quot;称号之前，都经过负责任的真实人类维护者审查。</li></ul><p>这些防护减少了意外或未经授权的模块执行。在你启用之后，它们不能让一个不可信的模块变得安全。源码链接和完整性检查是有用的证据，不能替代你的判断。</p><h2 id="提升你的安全性" tabindex="-1">提升你的安全性 <a class="header-anchor" href="#提升你的安全性" aria-label="Permalink to “提升你的安全性”">​</a></h2><ul><li>从你认识的来源安装模块。启用前审查模块的源码和它请求的功能，移除不再信任的模块源。</li><li>保持完整性验证开启。除非你明白为什么必须这样做，不要启用你不信任的模块或关闭验证。</li><li>避免 HTTP 源，尤其是在你无法控制的网络上。后端和模块源 URL 使用 HTTPS</li><li>对敏感仓库启用加密模块。使用强而唯一的密码，保存在 Obsidian 的密钥存储中，并在同步加密文件之前在每台设备上配置好。依赖它之前请阅读<a href="./../deep-dive/modules/encryption">加密规范</a>。</li><li>用操作系统的更新、账户保护和磁盘加密（如果可用）保护你的设备和 Obsidian 仓库。</li><li>只给你的后端账户授予 Sync Engine 所用目录的访问权限，并保留独立的备份。加密无法找回被恶意后端删除的数据。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};